AA+C;AAAA,aAA9B/oB,KAA8B,uEAAtBtB,YAAsB;AAAA,aAAR+hB,MAAQ;;AAClD,aAAIqI,SAAS1I,cAAT,CAAwBK,OAAO/e,IAA/B,CAAJ,EAA0C;AACtC,oBAAOonB,SAASrI,OAAO/e,IAAhB,EAAsB1B,KAAtB,EAA6BygB,MAA7B,CAAP;AACH,UAFD,MAEO;AACH,oBAAOzgB,KAAP;AACH;AACJ,MAND;AAOH,E;;;;;;;;;;;;;ACRD;;;;AACA;;KAAYS,K;;;;;;;;AAEL,KAAM8L,0CAAiB,6BAAc,EAAd,sBACzB9L,MAAMoB,cADmB,YACH7B,KADG,EACIygB,MADJ,EACY;AAClC,YAAOA,OAAOzf,IAAd;AACH,EAHyB,EAAvB;;AAMA,KAAMgK,kDAAqB,6BAAc,EAAd,sBAC7BvK,MAAMqB,cADuB,YACP9B,KADO,EACAygB,MADA,EACQ;AAClC,YAAOA,OAAOzf,IAAd;AACH,EAH6B,EAA3B;;AAMA,KAAM0B,gCAAY,6BAAc,EAAd,sBACpBjC,MAAMsB,cADc,YACE/B,KADF,EACSygB,MADT,EACiB;AAClC,YAAOA,OAAOzf,IAAd;AACH,EAHoB,EAAlB;;AAMA,KAAMoK,kCAAa,6BAAc,EAAd,sBACrB3K,MAAMyB,kBADe,YACKlC,KADL,EACYygB,MADZ,EACoB;AACtC,YAAOA,OAAOzf,IAAd;AACH,EAHqB,EAAnB;;AAMA,KAAME,gCAAY,6BAAc,EAAd,sBACpBT,MAAM0B,cADc,YACEnC,KADF,EACSygB,MADT,EACiB;AAClC,YAAOA,OAAOzf,IAAd;AACH,EAHoB,EAAlB;;AAMA,KAAM0L,0CAAiB,6BAAc,EAAd,sBACzBjM,MAAMuB,mBADmB,YACEhC,KADF,EACSygB,MADT,EACiB;AACvC,YAAOA,OAAOzf,IAAd;AACH,EAHyB,EAAvB;;AAMA,KAAMkM,8CAAmB,6BAAc,EAAd,sBAC3BzM,MAAMwB,oBADqB,YACCjC,KADD,EACQygB,MADR,EACgB;AACxC,YAAOA,OAAOzf,IAAd;AACH,EAH2B,EAAzB,C;;;;;;;;;;;;;ACvCP;;KAAYP,K;;AACZ;;;;;;;;;;AAEO,KAAMyK,4CAAkB,6BAAc,EAAd,sBAC1BzK,MAAM6C,oBADoB,YACEtD,KADF,EACSygB,MADT,EACiB;AACxC,YAAOA,OAAOzf,IAAd;AACH,EAH0B,EAAxB;;AAMA,KAAMwL,0CAAiB,6BAAc,EAAd,sBACzB/L,MAAM8C,mBADmB,YACEvD,KADF,EACSygB,MADT,EACiB;AACvC,YAAOA,OAAOzf,IAAd;AACH,EAHyB,EAAvB,C;;;;;;;;;;;;;ACTP;;KAAYP,K;;AACZ;;;;;;;;;;AAEO,KAAMqK,sDAAuB,6BAAc,EAAd,sBAC/BrK,MAAM+C,yBADyB,YACExD,KADF,EACSygB,MADT,EACiB;AAC7C,YAAOA,OAAOzf,IAAd;AACH,EAH+B,EAA7B;;AAMA,KAAMyL,8CAAmB,6BAAc,EAAd,sBAC3BhM,MAAMgD,gBADqB,YACHzD,KADG,EACIygB,MADJ,EACY;AACpC,YAAOA,OAAOzf,IAAd;AACH,EAH2B,EAAzB,C;;;;;;;;;;;;;ACTP;;KAAYP,K;;AACZ;;;;;;;;;;AAEO,KAAM8D,0CAAiB,6BAAc,EAAd,sBACzB9D,MAAMiD,mBADmB,YACE1D,KADF,EACSygB,MADT,EACiB;AACvC,YAAOA,OAAOzf,IAAd;AACH,EAHyB,EAAvB,C;;;;;;;;;;;;;ACHP;;KAAYP,K;;AACZ;;;;;;;;;;AAEO,KAAMb,gCAAY,6BAAc,EAAd,sBACpBa,MAAMkD,aADc,YACC3D,KADD,EACQygB,MADR,EACgB;AACjC,YAAOA,OAAOzf,IAAd;AACH,EAHoB,EAAlB,C","file":"www/js/build//dev/reactpages/subsidiaryperformance/subsidiaryperformance.chunk.js","sourcesContent":["import React from 'react'\r\nimport ReactDOM from 'react-dom';\r\nimport AppContainer from './AppContainer.jsx'\r\nimport { Provider } from 'react-redux'\r\nimport { createStore, applyMiddleware, combineReducers, compose } from 'redux'\r\nimport thunkMiddleware from 'redux-thunk'\r\nimport { createLogger } from 'redux-logger'\r\nimport reducer from '../reducers/index.js'\r\n\r\n// middleware that logs actions\r\nconst loggerMiddleware = createLogger();\r\n\r\nconst defaultState = Object.assign({}, window.Lrf);\r\n\r\nfunction configureStore(initialState) {\r\n  const enhancer = compose(\r\n    applyMiddleware(\r\n      thunkMiddleware, // lets us dispatch() functions\r\n      loggerMiddleware,\r\n    ),\r\n  );\r\n  return createStore(reducer, initialState, enhancer);\r\n}\r\n\r\nconst store = configureStore(defaultState);\r\n\r\nexport default class App extends React.Component {\r\n  constructor(props) {\r\n    super(props);\r\n  }\r\n\r\n  render() {\r\n    return (\r\n      <Provider store={store}>\r\n        <AppContainer />\r\n      </Provider>\r\n    );\r\n  }\r\n}\r\n\r\nReactDOM.render(<App />, document.getElementById(\"app-container\"));\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/pages/subsidiaryperformance/components/index.jsx","const DEFAULT_RESOURCE_NAME = \"_language_en_US\";\r\nconst langCode = window.PageLanguage || \"en-US\";\r\nconst resourceName = `_language_${langCode.replace(\"-\", \"_\")}`;\r\n\r\nexport default class LangHelper {\r\n    static get currentLanguage() {\r\n        return langCode;\r\n    }\r\n\r\n    static getSingleResource(key) {\r\n        var langHandler = window[resourceName];\r\n\r\n        return langHandler[key] || window[DEFAULT_RESOURCE_NAME][key] || key;\r\n    }\r\n}\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/lib/langHelper.js","import React, { Component } from 'react';\r\nimport { connect } from 'react-redux';\r\nimport { bindActionCreators } from 'redux'\r\nimport { ActionCreators } from '../actions/index'\r\nimport DataGrid from './datagrid'\r\nimport FormFilter from './formFilter'\r\nimport Loader from '../../../components/Loader'\r\nimport AppLayout from '../../../layouts/AppLayout'\r\n\r\nclass AppContainer extends Component {\r\n  constructor(props) {\r\n    super(props);\r\n  }\r\n\r\n  render() {\r\n    return (\r\n      <AppLayout>\r\n        <Loader isLoading={this.props.isLoading} />\r\n        <FormFilter />\r\n        <DataGrid />\r\n      </AppLayout>\r\n    );\r\n  }\r\n}\r\nfunction mapDispatchToProps(dispatch) {\r\n  return bindActionCreators(ActionCreators, dispatch);\r\n}\r\n\r\nfunction mapStateToProps(state) {\r\n  return Object.assign({}, { isLoading: state.isLoading });\r\n}\r\n\r\n\r\nexport default connect(mapStateToProps, mapDispatchToProps)(AppContainer);\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/pages/subsidiaryperformance/components/AppContainer.jsx","import * as dataHandlerAction from './dataHandlerAction.js'\r\nimport * as filterHandlerAction from './filterHandlerAction.js'\r\nimport * as productAction from '../../../actions/productAction'\r\nimport * as baseCurrencyAction from '../../../actions/baseCurrencyAction'\r\nimport * as loaderAction from '../../../actions/loaderAction'\r\n\r\nexport const ActionCreators = Object.assign({},\r\n    dataHandlerAction,\r\n    filterHandlerAction,\r\n    productAction,\r\n    baseCurrencyAction,\r\n    loaderAction\r\n);\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/pages/subsidiaryperformance/actions/index.js","import * as types from './types.js'\r\nimport axios from 'axios'\r\n\r\nimport * as site from '../../../lib/site'\r\n\r\nexport function fetchData(params) {\r\n    return (dispatch, getState) => {\r\n        const url = site.resolveClientUrl('api/SubsidiaryPerformanceReport/Index');\r\n        axios.post(url, params.data, {\r\n                headers: {\r\n                    'X-Requested-With': 'XMLHttpRequest',\r\n                    '__RequestVerificationToken': params.xsrfToken\r\n                }\r\n            })\r\n            .then(response => {\r\n                dispatch(setGridData(response.data));\r\n            })\r\n            .catch(function(error) {\r\n                console.log(\"error:\", error);\r\n            });\r\n    };\r\n}\r\n\r\nexport function setGridData(data) {\r\n    var result = {\r\n        type: types.SET_GRID_DATA,\r\n        data: data\r\n    };\r\n\r\n    return result;\r\n}\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/pages/subsidiaryperformance/actions/dataHandlerAction.js","export const FETCH_DATA = 'FETCH_DATA'\r\nexport const SET_GRID_DATA = \"SET_GRID_DATA\"\r\n\r\nexport const GET_SUBSIDIARY = \"GET_SUBSIDIARY\"\r\nexport const SET_SUBSIDIARY = \"SET_SUBSIDIARY\"\r\n\r\nexport const SET_DATE_RANGE = \"SET_DATE_RANGE\"\r\nexport const GET_DATE_CONSTRAINT = \"GET_DATE_CONSTRAINT\"\r\nexport const SET_VALID_DATE_RANGE = \"SET_VALID_DATE_RANGE\"\r\nexport const CHANGE_CONVERT_ALL = \"CHANGE_CONVERT_ALL\"\r\n\r\nexport const GET_XSRF_TOKEN = \"GET_XSRF_TOKEN\"\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/pages/subsidiaryperformance/actions/types.js","const _rootUrl = window.rootUrl || \"/\";\r\n\r\nexport function resolveClientUrl(relativeUrl) {\r\n    return _rootUrl + relativeUrl;\r\n}\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/lib/site.js","import * as types from './types.js'\r\n\r\nexport const setSelectedSubsidiary = (subsidiaryKeys) => {\r\n    return {\r\n        type: types.SET_SUBSIDIARY,\r\n        data: subsidiaryKeys\r\n    }\r\n}\r\n\r\nexport const setDateRange = (dateRange) => {\r\n    const range = {\r\n        fromDate: dateRange.startDate,\r\n        toDate: dateRange.endDate\r\n    }\r\n\r\n    return {\r\n        type: types.SET_DATE_RANGE,\r\n        data: range\r\n    }\r\n}\r\n\r\nexport const setValidDateRange = (isValid) => {\r\n    return {\r\n        type: types.SET_VALID_DATE_RANGE,\r\n        data: isValid\r\n    }\r\n}\r\n\r\nexport const changeConvertAll = (checked) => {\r\n    return {\r\n        type: types.CHANGE_CONVERT_ALL,\r\n        data: checked\r\n    }\r\n}\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/pages/subsidiaryperformance/actions/filterHandlerAction.js","import * as types from './types'\r\n\r\nexport const setSelectedProduct = (product) => {\r\n    return {\r\n        type: types.SET_SELECTED_PRODUCT,\r\n        data: product\r\n    };\r\n}\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/actions/productAction.js","/* Product */\r\nexport const SET_SELECTED_PRODUCT = \"SET_SELECTED_PRODUCT\";\r\nexport const GET_PRODUCT_OPTIONS = \"GET_PRODUCT_OPTIONS\";\r\n\r\n/* Base Currency */\r\nexport const SET_SELECTED_BASECURRENCY = \"SET_SELECTED_BASECURRENCY\";\r\nexport const GET_BASECURRENCY = \"GET_BASECURRENCY\";\r\n\r\n/* Fixed Table Header */\r\nexport const GET_CONTAINER_WIDTH = \"GET_CONTAINER_WIDTH\";\r\n\r\n/* Loader */\r\nexport const TOGGLE_LOADER = \"TOGGLE_LOADER\"\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/actions/types.js","import * as types from './types'\r\n\r\nexport const setSelectedBaseCurrency = (baseCurrency) => {\r\n    return {\r\n        type: types.SET_SELECTED_BASECURRENCY,\r\n        data: baseCurrency\r\n    }\r\n}\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/actions/baseCurrencyAction.js","import * as types from './types'\r\n\r\nexport const toggleLoader = (show) => {\r\n    return {\r\n        type: types.TOGGLE_LOADER,\r\n        data: show\r\n    }\r\n}\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/actions/loaderAction.js","import React, { Component } from 'react'\r\nimport { connect } from 'react-redux'\r\nimport { ActionCreators } from '../actions/index.js'\r\nimport { bindActionCreators } from 'redux'\r\nimport { Table, Header, Body, Footer, Row, Cell } from 'lrfcomponents/fixed-table-header/FixedTable'\r\nimport LangHelper from 'lrflib/langHelper'\r\nimport NumberFormat from 'lrflib/numberFormat'\r\n\r\nconst columnLayout = [150, 100, 200, 150, 200, 200, 200];\r\n\r\nclass DataGrid extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n    }\r\n\r\n    get header() {\r\n        const subsidiary = LangHelper.getSingleResource(\"Subsidiary\"),\r\n            currency = LangHelper.getSingleResource(\"Currency\"),\r\n            product = LangHelper.getSingleResource(\"Product\"),\r\n            betcount = LangHelper.getSingleResource(\"BetCount\"),\r\n            turnover = LangHelper.getSingleResource(\"Turnover\"),\r\n            customerWL = LangHelper.getSingleResource(\"CustomerWinLoss\"),\r\n            subsidiaryWL = LangHelper.getSingleResource(\"SubsidiaryWL\"),\r\n            comm = LangHelper.getSingleResource(\"Comm\");\r\n\r\n        return (\r\n            <Row style={{ height: 40 }}>\r\n                <th title={subsidiary}>{subsidiary}</th>\r\n                <th title={currency}>{currency}</th>\r\n                <th title={product}>{product}</th>\r\n                <th title={betcount}>{betcount}</th>\r\n                <th title={turnover}>{turnover}</th>\r\n                <th title={customerWL}>{customerWL}</th>\r\n                <th title={`${subsidiaryWL}/ ${comm}`}>{`${subsidiaryWL}/ ${comm}`}</th>\r\n            </Row>\r\n        )\r\n    }\r\n\r\n    get body() {\r\n        const data = this.props.gridData.Data;\r\n        let rows = [];\r\n        for (let i = 0; i < data.length; i++) {\r\n            const item = data[i];\r\n            const rowSpan = item.Details.length;\r\n\r\n            let isFirstRow = true;\r\n            for (let j = 0; j < item.Details.length; j++) {\r\n                const detail = item.Details[j];\r\n                const betcount = NumberFormat.format(detail.BetCount),\r\n                    turnover = NumberFormat.formatDecimal(detail.Turnover),\r\n                    customerWinLoss = NumberFormat.formatDecimal(detail.CustomerWinLoss),\r\n                    subsidiaryWinLoss = NumberFormat.formatDecimal(detail.SubsidiaryWinLoss);\r\n\r\n                rows.push(\r\n                    <Row key={`tr${i}${j}`}>\r\n                        {isFirstRow ? <Cell title={item.Subsidiary} rowSpan={rowSpan}>{item.Subsidiary}</Cell> : undefined}\r\n                        {isFirstRow ? <Cell title={item.CurrencyName} rowSpan={rowSpan} className=\"center-align\">{item.CurrencyName}</Cell> : undefined}\r\n                        <Cell title={detail.Product}>{detail.Product}</Cell>\r\n                        <Cell title={betcount} className=\"right-align\">{betcount}</Cell>\r\n                        <Cell title={turnover} className=\"right-align\">{turnover}</Cell>\r\n                        <Cell title={customerWinLoss} className=\"right-align\">{customerWinLoss}</Cell>\r\n                        <Cell title={subsidiaryWinLoss} className={`right-align ${detail.SubsidiaryWinLoss < 0 ? \"negative\" : \"\"}`}>\r\n                            {subsidiaryWinLoss}\r\n                        </Cell>\r\n                    </Row>\r\n                );\r\n\r\n                isFirstRow = false;\r\n            }\r\n        }\r\n\r\n        return rows;\r\n    }\r\n\r\n    get footer() {\r\n        const totalData = this.props.gridData.Total;\r\n        return totalData.map((item, index) => {\r\n            const betcount = NumberFormat.format(item.BetCount),\r\n                turnover = NumberFormat.formatDecimal(item.Turnover),\r\n                customerWinLoss = NumberFormat.formatDecimal(item.CustomerWinLoss),\r\n                subsidiaryWinLoss = NumberFormat.formatDecimal(item.SubsidiaryWinLoss);\r\n\r\n            return (\r\n                <Row className=\"fixed-table-total\" key={`total${index}`}>\r\n                    <Cell title={item.Subsidiary}>{item.Subsidiary}</Cell>\r\n                    <Cell title={item.CurrencyName}>{item.CurrencyName}</Cell>\r\n                    <Cell></Cell>\r\n                    <Cell title={betcount} className=\"right-align\">{betcount}</Cell>\r\n                    <Cell title={turnover} className=\"right-align\">{turnover}</Cell>\r\n                    <Cell title={customerWinLoss} className=\"right-align\">{customerWinLoss}</Cell>\r\n                    <Cell title={subsidiaryWinLoss} className={`right-align ${item.SubsidiaryWinLoss < 0 ? \"negative\" : \"\"}`}>\r\n                        {subsidiaryWinLoss}\r\n                    </Cell>\r\n                </Row>\r\n            )\r\n        })\r\n    }\r\n\r\n    get grantTotal() {\r\n        const grandTotal = this.props.gridData.GrandTotal;\r\n        if (!grandTotal) return null;\r\n\r\n        const betcount = NumberFormat.format(grandTotal.BetCount),\r\n            turnover = NumberFormat.formatDecimal(grandTotal.Turnover),\r\n            customerWinLoss = NumberFormat.formatDecimal(grandTotal.CustomerWinLoss),\r\n            subsidiaryWinLoss = NumberFormat.formatDecimal(grandTotal.SubsidiaryWinLoss);\r\n\r\n        return (\r\n            <Row className=\"fixed-table-grant-total\">\r\n                <Cell title={grandTotal.Subsidiary}>{grandTotal.Subsidiary}</Cell>\r\n                <Cell title={grandTotal.CurrencyName}>{grandTotal.CurrencyName}</Cell>\r\n                <Cell></Cell>\r\n                <Cell title={betcount} className=\"right-align\">{betcount}</Cell>\r\n                <Cell title={turnover} className=\"right-align\">{turnover}</Cell>\r\n                <Cell title={customerWinLoss} className=\"right-align\">{customerWinLoss}</Cell>\r\n                <Cell title={subsidiaryWinLoss} className=\"right-align\">{subsidiaryWinLoss}</Cell>\r\n            </Row>\r\n        )\r\n    }\r\n\r\n    componentDidUpdate(prevProps, prevState) {\r\n        this.props.toggleLoader(false);\r\n    