        {name}\r\n        </a>\r\n      );\r\n    });\r\n  }\r\n\r\n  renderRangeButtons(classes) {\r\n    const { style, onlyClasses, locale } = this.props;\r\n    const locales = { ...defaultOptions.locale, ...locale };\r\n    const { styles } = this;\r\n    const action = {\r\n      apply: \"apply\",\r\n      cancel: \"cancel\"\r\n    }\r\n\r\n    return (\r\n      <div className={defaultClasses.rangeButtonGroup}>\r\n        <button className={classes.applyButton}\r\n          style={onlyClasses ? undefined : { ...styles['RangeApplyButton'], ...style }}\r\n          type=\"button\"\r\n          onClick={(e) => this.clickButton(e, action.apply)}>\r\n          {locales.applyLabel}\r\n        </button>\r\n\r\n        <button className={classes.cancelButton}\r\n          style={onlyClasses ? undefined : { ...styles['RangeCancelButton'], ...style }}\r\n          onClick={(e) => this.clickButton(e, action.cancel)}\r\n          type=\"button\">\r\n          {locales.cancelLabel}\r\n        </button>\r\n      </div>\r\n    )\r\n  }\r\n\r\n  render() {\r\n    const { style, onlyClasses, classNames } = this.props;\r\n    const { styles } = this;\r\n\r\n    const classes = { ...defaultClasses, ...classNames };\r\n\r\n    return (\r\n      <div\r\n        style={onlyClasses ? undefined : { ...styles['PredefinedRanges'], ...style }}\r\n        className={classes.predefinedRanges}\r\n      >\r\n        {this.renderRangeList(classes)}\r\n        {this.renderRangeButtons(classes)}\r\n      </div>\r\n    );\r\n  }\r\n}\r\n\r\nPredefinedRanges.defaultProps = {\r\n  onlyClasses: false,\r\n  classNames: {}\r\n};\r\n\r\nPredefinedRanges.propTypes = {\r\n  ranges: PropTypes.object.isRequired,\r\n  onlyClasses: PropTypes.bool,\r\n  classNames: PropTypes.object\r\n}\r\n\r\nexport default PredefinedRanges;\r\n\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/components/date-range/PredefinedRanges.js","import LangHelper from \"lrflib/langHelper\";\r\n\r\nexport default {\r\n    ranges: {\r\n        [LangHelper.getSingleResource(\"Today\")]: {\r\n            startDate: (now) => {\r\n                return now;\r\n            },\r\n            endDate: (now) => {\r\n                return now;\r\n            }\r\n        },\r\n\r\n        [LangHelper.getSingleResource(\"Yesterday\")]: {\r\n            startDate: (now) => {\r\n                return now.add(-1, 'days');\r\n            },\r\n            endDate: (now) => {\r\n                return now.add(-1, 'days');\r\n            }\r\n        },\r\n\r\n        [LangHelper.getSingleResource(\"Currentweek\")]: {\r\n            startDate: (now) => {\r\n                return now.startOf('week');\r\n            },\r\n            endDate: (now) => {\r\n                return now;\r\n            }\r\n        },\r\n\r\n        [LangHelper.getSingleResource(\"Lastweek\")]: {\r\n            startDate: (now) => {\r\n                return now.subtract(1, 'week').startOf('week');\r\n            },\r\n            endDate: (now) => {\r\n                return now.subtract(1, 'week').startOf('week').add(6, 'days');\r\n            }\r\n        },\r\n\r\n        [LangHelper.getSingleResource(\"Currentmonth\")]: {\r\n            startDate: (now) => {\r\n                return now.startOf('month');\r\n            },\r\n            endDate: (now) => {\r\n                return now;\r\n            }\r\n        },\r\n\r\n        [LangHelper.getSingleResource(\"Lastmonth\")]: {\r\n            startDate: (now) => {\r\n                return now.subtract(1, 'month').startOf('month');\r\n            },\r\n            endDate: (now) => {\r\n                return now.subtract(1, 'month').endOf('month');\r\n            }\r\n        },\r\n\r\n        [LangHelper.getSingleResource(\"Sincelastmonth\")]: {\r\n            startDate: (now) => {\r\n                return now.subtract(1, 'month').startOf('month');\r\n            },\r\n            endDate: (now) => {\r\n                return now;\r\n            }\r\n        }\r\n    },\r\n\r\n    locale: {\r\n        applyLabel: LangHelper.getSingleResource(\"OK\"),\r\n        cancelLabel: LangHelper.getSingleResource(\"Cancel\")\r\n    }\r\n}\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/components/date-range/defaultOptions.js","import moment from 'moment';\r\nimport LangHelper from 'lrflib/langHelper';\r\n\r\nexport default function updateLocaleByLanguage(langKey) {\r\n    moment.updateLocale(langKey, {\r\n        months: [\r\n            LangHelper.getSingleResource('Jan'), LangHelper.getSingleResource('Feb'),\r\n            LangHelper.getSingleResource('Mar'), LangHelper.getSingleResource('Apr'),\r\n            LangHelper.getSingleResource('May'), LangHelper.getSingleResource('Jun'),\r\n            LangHelper.getSingleResource('Jul'), LangHelper.getSingleResource('Aug'),\r\n            LangHelper.getSingleResource('Sep'), LangHelper.getSingleResource('Oct'),\r\n            LangHelper.getSingleResource('Nov'), LangHelper.getSingleResource('Dec')\r\n        ]\r\n    });\r\n\r\n    moment.locale(langKey);\r\n}\n\n\n// WEBPACK FOOTER //\n// ./www/js/source/reactpages/components/date-range/utils/locale.js","import Excel from 'lrflib/excel'\r\nimport LangHelper from 'lrflib/langHelper'\r\nimport * as excelStyle from 'lrflib/excelStyle'\r\n\r\nconst COLUMN_COUNT = 7;\r\nconst START_OF_DATA_ROW = 1;\r\n\r\nconst SUBSIDIARY_COLUMN_INDEX = 0;\r\nconst CURRENCY_COLUMN_INDEX = 1;\r\nconst PRODUCT_COLUMN_INDEX = 2;\r\nconst BETCOUNT_COLUMN_INDEX = 3;\r\nconst TURNOVER_COLUMN_INDEX = 4;\r\nconst CUSTOMERWL_COLUMN_INDEX = 5;\r\nconst SUBSIDIARYWL_COLUMN_INDEX = 6;\r\n\r\nconst MAIN_SECTION_NAME = \"mainSection\";\r\nconst TOTAL_SECTION_NAME = \"totalSection\";\r\nconst GRAND_TOTAL_SECTION_NAME = \"grandTotalSection\";\r\n\r\nconst columnConfigs = [{\r\n        field: \"Subsidiary\",\r\n        [MAIN_SECTION_NAME]: \"ROW_SPAN_CELL_STYLE\",\r\n        [TOTAL_SECTION_NAME]: \"TOTAL_CELL_STYLE\",\r\n        [GRAND_TOTAL_SECTION_NAME]: \"GRAND_TOTAL_CELL_STYLE\"\r\n    },\r\n    {\r\n        field: \"CurrencyName\",\r\n        [MAIN_SECTION_NAME]: \"ROW_SPAN_CENTER_CELL_STYLE\",\r\n        [TOTAL_SECTION_NAME]: \"TOTAL_CELL_STYLE\",\r\n        [GRAND_TOTAL_SECTION_NAME]: \"GRAND_TOTAL_CELL_STYLE\"\r\n    },\r\n    {\r\n        field: \"Product\",\r\n        [MAIN_SECTION_NAME]: \"\",\r\n        [TOTAL_SECTION_NAME]: \"\",\r\n        [GRAND_TOTAL_SECTION_NAME]: \"GRAND_TOTAL_CELL_STYLE\"\r\n    },\r\n    {\r\n        field: \"BetCount\",\r\n        [MAIN_SECTION_NAME]: \"NUMBER_CELL_STYLE\",\r\n        [TOTAL_SECTION_NAME]: \"TOTAL_NUMBER_CELL_STYLE\",\r\n        [GRAND_TOTAL_SECTION_NAME]: \"GRAND_TOTAL_CELL_STYLE\"\r\n    },\r\n    {\r\n        field: \"Turnover\",\r\n        [MAIN_SECTION_NAME]: \"DECIMAL_CELL_STYLE\",\r\n        [TOTAL_SECTION_NAME]: \"TOTAL_DECIMAL_CELL_STYLE\",\r\n        [GRAND_TOTAL_SECTION_NAME]: \"GRAND_TOTAL_NUMBER_CELL_STYLE\"\r\n    },\r\n    {\r\n        field: \"CustomerWinLoss\",\r\n        [MAIN_SECTION_NAME]: \"DECIMAL_CELL_STYLE\",\r\n        [TOTAL_SECTION_NAME]: \"TOTAL_DECIMAL_CELL_STYLE\",\r\n        [GRAND_TOTAL_SECTION_NAME]: \"GRAND_TOTAL_NUMBER_CELL_STYLE\"\r\n    },\r\n    {\r\n        field: \"SubsidiaryWinLoss\",\r\n        [MAIN_SECTION_NAME]: \"DECIMAL_CELL_STYLE\",\r\n        [TOTAL_SECTION_NAME]: \"TOTAL_DECIMAL_CELL_STYLE\",\r\n        [GRAND_TOTAL_SECTION_NAME]: \"GRAND_TOTAL_NUMBER_CELL_STYLE\"\r\n    }\r\n]\r\n\r\nconst HEADERS = [\r\n    LangHelper.getSingleResource(\"Subsidiary\"), LangHelper.getSingleResource(\"Currency\"),\r\n    LangHelper.getSingleResource(\"Product\"), LangHelper.getSingleResource(\"BetCount\"),\r\n    LangHelper.getSingleResource(\"Turnover\"), LangHelper.getSingleResource(\"CustomerWinLoss\"),\r\n    `${LangHelper.getSingleResource(\"SubsidiaryWL\")}/ ${LangHelper.getSingleResource(\"Comm\")}`\r\n];\r\n\r\nexport default class ReportExcel {\r\n    constructor(gridData = [], fileName = \"SubsidiaryPerformance\") {\r\n       